import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './Dashboard.css';

const Dashboard = () => {
  const [coaches, setCoaches] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  const [gymStats, setGymStats] = useState({
    totalMembers: 0,
    activeMembers: 0,
    upcomingSessions: 0,
    totalClasses: 0,
  });

  const [upcomingClasses, setUpcomingClasses] = useState([]);

  // Fetch coaches and gym stats when the component loads
  useEffect(() => {
    async function fetchData() {
      try {
        // Fetch coaches
        const coachesResponse = await axios.get('http://localhost:5000/api/coach');
        setCoaches(coachesResponse.data);
        
        // Fetch gym stats (you'll need to implement this endpoint)
        const statsResponse = await axios.get('http://localhost:5000/api/gym/stats');
        setGymStats(statsResponse.data);
        
        // Fetch upcoming classes (you'll need to implement this endpoint)
        const classesResponse = await axios.get('http://localhost:5000/api/classes/upcoming');
        setUpcomingClasses(classesResponse.data);
        
        setIsLoading(false);
      } catch (error) {
        console.error('Error fetching data:', error);
        setError(error.message);
        setIsLoading(false);
      }
    }
    fetchData();
  }, []);

  if (isLoading) {
    return <div className="dashboard-loading">Loading...</div>;
  }

  if (error) {
    return <div className="dashboard-error">Error: {error}</div>;
  }

  return (
    <div className="dashboard">
      <header className="dashboard-header">
        <h2>Gym Management Dashboard</h2>
        <p>View all coaches, gym statistics, and upcoming classes.</p>
      </header>

      <div className="dashboard-body">
        <div className="dashboard-left">
          {/* Gym Stats */}
          <div className="stats-card">
            <h3>Gym Statistics</h3>
            <div className="stats-grid">
              <div className="stat-item">
                <h4>Total Members</h4>
                <p>{gymStats.totalMembers}</p>
              </div>
              <div className="stat-item">
                <h4>Active Members</h4>
                <p>{gymStats.activeMembers}</p>
              </div>
              <div className="stat-item">
                <h4>Total Classes</h4>
                <p>{gymStats.totalClasses}</p>
              </div>
              <div className="stat-item">
                <h4>Upcoming Sessions</h4>
                <p>{gymStats.upcomingSessions}</p>
              </div>
            </div>
          </div>

          {/* All Coaches Section */}
          <div className="coaches-section">
            <h3>All Coaches</h3>
            <div className="coaches-grid">
              {coaches.map((coach) => (
                <div className="coach-card" key={coach._id}>
                  <div className="coach-image-wrapper">
                    <img 
                      src={coach.profilePicture || 'https://via.placeholder.com/150'} 
                      alt={`${coach.name}'s profile`} 
                      className="coach-image" 
                    />
                  </div>
                  <div className="coach-details">
                    <h4>{coach.name}</h4>
                    <p><strong>Email:</strong> {coach.email}</p>
                    <p><strong>Specialization:</strong> {coach.specialization || 'General Fitness'}</p>
                    <p><strong>Experience:</strong> {coach.experience || 'Not specified'}</p>
                    <p><strong>Certifications:</strong> {coach.certifications?.join(', ') || 'None listed'}</p>
                    <p><strong>Bio:</strong> {coach.bio || 'No bio available'}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        <div className="dashboard-right">
          {/* Upcoming Classes */}
          <div className="classes-card">
            <h3>Upcoming Classes</h3>
            {upcomingClasses.length > 0 ? (
              <ul className="classes-list">
                {upcomingClasses.map((classItem) => (
                  <li key={classItem._id} className="class-item">
                    <div className="class-time">{classItem.time}</div>
                    <div className="class-info">
                      <strong>{classItem.className}</strong>
                      <p>Location: {classItem.location}</p>
                      <p>Instructor: {classItem.instructor}</p>
                    </div>
                  </li>
                ))}
              </ul>
            ) : (
              <p>No upcoming classes scheduled.</p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
